import { shouldPromptRegenerateImportedUuid } from '../store/projectHelpers.js';
import { generateUuid } from '../utils/uuid.js';

// Nouvelle révision d'un pack repris par « Modifier un pack » : proposer, sans
// obligation, un nouvel UUID avant de générer. Le Libre et le graphe posent la
// même question, au même moment — avant le sélecteur de dossier de sortie, un
// dialogue natif qui passerait devant.
//
// Rend le brouillon, avec un UUID neuf si l'auteur le demande.
export async function askImportedUuidRevision(draft, showChoiceDialog) {
  if (!shouldPromptRegenerateImportedUuid(draft)) return draft;
  const choice = await showChoiceDialog({
    title: "Nouvelle révision d'un pack importé",
    message: "Ce pack a un UUID d'origine. Générer un nouvel UUID pour cette version ?\n\n"
      + "Garde l'UUID d'origine seulement pour remplacer exactement la même révision.",
    variant: 'info',
    cancelValue: 'keep',
    actions: [
      { value: 'keep', label: "Garder l'UUID d'origine", kind: 'ghost' },
      { value: 'renew', label: 'Générer un nouvel UUID', kind: 'primary', autoFocus: true },
    ],
  });
  return choice === 'renew' ? { ...draft, uuid: generateUuid() } : draft;
}

sources.src/hooks/mediaLibraryImport.js:
const AUDIO_EXTENSIONS = new Set(['mp3', 'wav', 'ogg', 'm4a', 'flac', 'webm']);

function extension(path) {
  return (String(path).split('.').pop() || '').toLowerCase();
}

function isAudioPath(path) {
  return AUDIO_EXTENSIONS.has(extension(path));
}

function basename(path) {
  const normalized = String(path || '').replace(/\\/g, '/');
  return normalized.slice(normalized.lastIndexOf('/') + 1);
}

export async function importFilesToMediaLibrary({
  files,
  maybeCopyToProject,
  copyGeneratedMediaToProject,
  extractAudioEmbeddedImage,
  setImporting,
  getImportDisplayName = (path) => basename(path) || path,
}) {
  const nextPaths = [];
  const total = files.length;
  for (let i = 0; i < files.length; i += 1) {
    const file = files[i];
    const displayName = getImportDisplayName(file);
    setImporting({ name: displayName, index: i + 1, total, phase: 'Copie dans le projet...' });
    const copiedPath = await maybeCopyToProject(file);
    nextPaths.push(copiedPath);

    if (!extractAudioEmbeddedImage || !isAudioPath(copiedPath)) continue;
    setImporting({ name: displayName, index: i + 1, total, phase: 'Extraction de la jaquette...' });
    const embeddedImage = await extractAudioEmbeddedImage(copiedPath);
    if (embeddedImage) {
      const persistExtractedImage = copyGeneratedMediaToProject ?? maybeCopyToProject;
      nextPaths.push(await persistExtractedImage(embeddedImage));
    }
  }
  return nextPaths;
}

